using Grasshopper; using Grasshopper.Kernel; using Grasshopper.Kernel.Types; using Grasshopper.Kernel.Special; using Rhino.Geometry;
var io=new GH_DocumentIO(); io.Open(@"C:\Users\gonza\Documents\GitHub\pyramid-roof\polyframe2\friend-15-pyramid-branches-flatcorners.gh"); var doc=io.Document;
var sE=doc.Objects.OfType<GH_NumberSlider>().First(s=>s.NickName=="Eave edge height above wall top (mm)"); sE.Slider.Minimum=0; sE.SetSliderValue(0);
foreach(var p in doc.Objects.OfType<GH_Panel>().Where(p=>p.NickName=="Flat corners - read me")) p.UserText="Eave edge set to the BASE OF THE SHELL (wall-top level, slider = 0): the skin now comes all the way down to where the dome feet sit, and each corner ends at the plan corner of the eave at that same level. All struts then run horizontally at base level from the feet: side struts to the eave points, corner struts (V) to the corner. NOTE: horizontal struts carry the eave/corner weight by bending (cantilevers off the feet), not by compression - check in Karamba once the skin weight is known; slide the eave height up to make them sloped again.";
doc.Enabled=true; doc.NewSolution(false);
foreach(var o in doc.Objects.OfType<IGH_ActiveObject>()) if(o.RuntimeMessageLevel==GH_RuntimeMessageLevel.Error) Console.WriteLine("ERR "+o.NickName+": "+string.Join("|",o.RuntimeMessages(GH_RuntimeMessageLevel.Error)));
var mg=doc.Objects.OfType<IGH_Component>().Where(c=>c.Name=="Merge").Select(c=>c.Params.Output[0].VolatileData.AllData(true).OfType<GH_Line>().Select(x=>x.Value).ToList()).Where(l=>l.Count==24 && l.All(x=>Math.Min(x.From.Z,x.To.Z)<50)).FirstOrDefault();
if(mg!=null) Console.WriteLine("struts "+mg.Count+": "+string.Join(" ",mg.Select(l=>(l.Length/1000).ToString("0.00")+"m z"+(l.From.Z/1000).ToString("0.0")+"-"+(l.To.Z/1000).ToString("0.0")).Distinct()));
foreach(var p in doc.Objects.OfType<GH_Panel>().Where(p=>p.SourceCount>0 && (p.NickName.StartsWith("Eave")||p.NickName.StartsWith("Strut")||p.NickName.StartsWith("Dome nodes")))) Console.WriteLine(p.NickName+": "+string.Join(" ",p.VolatileData.AllData(true)));
var arch=new GH_IO.Serialization.GH_Archive(); arch.CreateNewRoot(false); arch.AppendObject(doc,"Definition"); Console.WriteLine("write "+arch.WriteToFile(@"C:\Users\gonza\Documents\GitHub\pyramid-roof\polyframe2\friend-15-pyramid-branches-atbase.gh",true,false));
var old=Instances.ActiveCanvas.Document; Instances.DocumentServer.AddDocument(doc); Instances.ActiveCanvas.Document=doc; if(old!=null){ old.Enabled=false; Instances.DocumentServer.RemoveDocument(old); old.Dispose(); }
doc.NewSolution(false);
